changeSet.sql:
DELETE rp FROM m_role_permission rp
JOIN m_permission p ON p.id = rp.permission_id
WHERE p.code IN ('READ_Multi-tranche eligibility', 'READ_Multi-tranche pipeline', 'READ_Multi-tranche amounts');
DELETE FROM m_permission
WHERE code IN ('READ_Multi-tranche eligibility', 'READ_Multi-tranche pipeline', 'READ_Multi-tranche amounts');
DELETE FROM stretchy_report_parameter
WHERE report_id IN (SELECT id FROM stretchy_report
    WHERE report_name IN ('Multi-tranche eligibility', 'Multi-tranche pipeline', 'Multi-tranche amounts'));
DELETE FROM stretchy_report
WHERE report_name IN ('Multi-tranche eligibility', 'Multi-tranche pipeline', 'Multi-tranche amounts');

UPDATE stretchy_report_parameter srp JOIN stretchy_report sr ON sr.id = srp.report_id JOIN stretchy_parameter oldp ON oldp.id = srp.parameter_id JOIN stretchy_parameter newp ON newp.parameter_name = 'startDateSelect' SET srp.parameter_id = newp.id WHERE sr.report_name = 'Multi-tranche pipeline Report' AND srp.report_parameter_name = 'startDate' AND oldp.parameter_name = 'tranchePipelineStartDate';
UPDATE stretchy_report_parameter srp JOIN stretchy_report sr ON sr.id = srp.report_id JOIN stretchy_parameter oldp ON oldp.id = srp.parameter_id JOIN stretchy_parameter newp ON newp.parameter_name = 'endDateSelect' SET srp.parameter_id = newp.id WHERE sr.report_name = 'Multi-tranche pipeline Report' AND srp.report_parameter_name = 'endDate' AND oldp.parameter_name = 'tranchePipelineEndDate';
UPDATE stretchy_report_parameter srp JOIN stretchy_report sr ON sr.id = srp.report_id JOIN stretchy_parameter oldp ON oldp.id = srp.parameter_id JOIN stretchy_parameter newp ON newp.parameter_name = 'LoanAccountStatus' SET srp.parameter_id = newp.id WHERE sr.report_name = 'Multi-tranche pipeline Report' AND srp.report_parameter_name = 'loanStatusId' AND oldp.parameter_name = 'trancheLoanStatusSelectAll';

UPDATE stretchy_report
SET report_sql = REPLACE(report_sql, 'COALESCE(ml.multi_disburse_loan, 1) = 1', 'ml.multi_disburse_loan = 1')
WHERE report_name = 'Multi-tranche pipeline Report';
